const JOIN_ECHO_RE = /^\[(2[0-3]|[01]\d):([0-5]\d):([0-5]\d)\] \[Server thread\/INFO\]: (\S+) joined the game$/

/**
 * The storm eighth breath census - the storm cadence list's own
 * EIGHTH GAP the adjacent pair at index seven prices (the .364 storm
 * first breath the opening prices, the .366 storm second breath the
 * runner-up priced, the .368 storm third breath the third priced,
 * the .370 storm fourth breath the fourth priced, the .372 storm
 * fifth breath the fifth priced, the .374 storm sixth breath the
 * sixth priced, the .376 storm seventh breath the seventh priced,
 * the eighth this seat keeps).
 *
 * @param {string[]} lines - the server console face's own lines
 * @returns {{rejoinStormEighthBreath: number}|null} the eighth gap or null (non-array)
 */
export function rejoinStormEighthBreathCensus (lines) {
  if (!Array.isArray(lines)) return null
  const tally = new Map()
  const revts = [] // the re-join events (beyond each name's first) the FILE ORDER keeps
  for (const l of lines) {
    if (typeof l !== 'string') continue
    const m = JOIN_ECHO_RE.exec(l)
    if (!m) continue
    const n = (tally.get(m[4]) || 0) + 1
    tally.set(m[4], n)
    if (n > 1) revts.push(Number(m[1]) * 3600 + Number(m[2]) * 60 + Number(m[3]))
  }
  const gaps = []
  for (let i = 1; i < revts.length; i++) {
    const cur = revts[i - 1]
    const nxt = revts[i]
    gaps.push(nxt >= cur ? nxt - cur : nxt + 86400 - cur) // the day-cyclic wrap
  }
  return { rejoinStormEighthBreath: gaps.length > 7 ? gaps[7] : 0 } // the EIGHTH the list keeps (the constructive zero the fewer-than-eight-gaps convention keeps)
}

